//
//  ThemeCatalogLoader.swift
//  GuacTerm
//
//  Reads the vendored iTerm2 color schemes from the bundled Themes.json.
//
//  The JSON is generated by scripts/generate-themes.swift and holds one object per
//  scheme:
//
//      {"id":"3024-night","name":"3024 Night","bg":"#090300",
//       "fg":"#BBBBBB","cursor":"#BBBBBB","ansi":["#090300", ... 16 values]}
//
//  Parsing happens once, lazily, and never throws at the call site: a missing or
//  damaged resource degrades the catalog to the two signature themes instead of
//  crashing the app or leaving the picker empty.
//

import Foundation

/// One element of Themes.json, before it becomes a `TerminalTheme`.
private struct VendoredTheme: Decodable {
    let id: String
    let name: String
    let bg: String
    let fg: String
    let cursor: String
    let ansi: [String]
}

enum ThemeCatalogLoader {
    /// Number of colors every scheme must carry (ANSI 0-15).
    private static let ansiCount = 16

    private static let resourceName = "Themes"
    private static let resourceExtension = "json"

    /// The vendored schemes, sorted by name (``NamedTheme/nameOrder(_:_:)``,
    /// the same rule the generator writes the file with).
    ///
    /// `static let` is lazily initialised exactly once and is thread-safe, which
    /// is all the concurrency handling Swift 6 needs here: `[TerminalTheme]` is
    /// `Sendable`, so no locking or `@MainActor` hops are involved.
    static let themes: [TerminalTheme] = load()

    // MARK: - Loading

    private static func load() -> [TerminalTheme] {
        guard let url = Bundle.main.url(
            forResource: resourceName,
            withExtension: resourceExtension
        ) else {
            NSLog(
                "GuacTerm: %@.%@ is not in the app bundle; offering only the built-in themes.",
                resourceName, resourceExtension
            )
            return []
        }

        let data: Data
        do {
            data = try Data(contentsOf: url)
        } catch {
            NSLog(
                "GuacTerm: could not read %@.%@ (%@); offering only the built-in themes.",
                resourceName, resourceExtension, String(describing: error)
            )
            return []
        }

        return themes(from: data)
    }

    /// The decoding half of ``load()``, given the bytes rather than the bundle.
    ///
    /// Separated because the file it normally reads only exists inside a built
    /// app, and the interesting cases here are the damaged ones: a truncated
    /// resource, a scheme missing a colour, two schemes sharing an identifier.
    /// None of them may throw or crash — the app loses the vendored catalog and
    /// keeps its own two themes.
    static func themes(from data: Data) -> [TerminalTheme] {
        let decoded: [VendoredTheme]
        do {
            decoded = try JSONDecoder().decode([VendoredTheme].self, from: data)
        } catch {
            NSLog(
                "GuacTerm: could not read %@.%@ (%@); offering only the built-in themes.",
                resourceName, resourceExtension, String(describing: error)
            )
            return []
        }

        var seenIDs = Set<String>()
        let themes = decoded
            .compactMap { theme(from: $0) }
            .filter { seenIDs.insert($0.id).inserted }
            .sorted(by: TerminalTheme.nameOrder)

        if themes.count != decoded.count {
            NSLog(
                "GuacTerm: skipped %ld unusable entries in %@.%@.",
                decoded.count - themes.count, resourceName, resourceExtension
            )
        }
        if themes.isEmpty {
            NSLog(
                "GuacTerm: %@.%@ holds no usable schemes; offering only the built-in themes.",
                resourceName, resourceExtension
            )
        }
        return themes
    }

    /// Converts one decoded entry, rejecting anything that would make the UI
    /// draw garbage (empty id, wrong color count, malformed hex).
    ///
    /// `isLight` is not decoded: ``TerminalTheme`` derives it from the
    /// background, so a vendored scheme and the same file imported through
    /// `ThemeLibrary` cannot disagree about it.
    private static func theme(from entry: VendoredTheme) -> TerminalTheme? {
        guard !entry.id.isEmpty, !entry.name.isEmpty, entry.ansi.count == ansiCount,
              TerminalTheme.isHexColor(entry.bg),
              TerminalTheme.isHexColor(entry.fg),
              TerminalTheme.isHexColor(entry.cursor),
              entry.ansi.allSatisfy(TerminalTheme.isHexColor) else { return nil }

        return TerminalTheme(
            id: entry.id,
            name: entry.name,
            background: entry.bg,
            foreground: entry.fg,
            cursor: entry.cursor,
            ansi: entry.ansi
        )
    }
}
